 const V=$('#dv'),tabs=[$('#d1'),$('#d2'),$('#d3')],show=i=>{tabs.forEach((t,j)=>t.className=i==j?'on':'');V.replaceChildren();[ov,ls,py][i]()};tabs.forEach((t,i)=>t.onclick=()=>show(i));
